static int depth(int n) {
    return depth(n + 1);   // never returns
}

public static void main(String[] args) {
    depth(0);
}

static final List<String> log = new ArrayList<>();   // one object

public static void main(String[] args) throws Exception {
    Thread a = new Thread(() -> log.add("a"));
    Thread b = new Thread(() -> log.add("b"));
    a.start();
    b.start();
    a.join();
    b.join();
    System.out.println(log.size());
}

